// resolveEnvTokenStatusTarget builds the status target from ENTIRE_TOKEN. The
// core is the token's aud (the same origin coreapi.New dials and the same
// validation it applies via CoreURLFromEnvToken), and the token is the bearer.
// Fail-closed, matching coreapi.New: a blank or malformed value is an error,
// never a silent fall-back to a stored context.
func resolveEnvTokenStatusTarget(raw string) (statusTarget, error) {
	token := strings.TrimSpace(raw)
	if token == "" {
		return statusTarget{}, fmt.Errorf("%s is set but blank", auth.EnvTokenVar)
	}
	coreURL, err := auth.CoreURLFromEnvToken(token)
	if err != nil {
		return statusTarget{}, err //nolint:wrapcheck // CoreURLFromEnvToken already prefixes with EnvTokenVar
	}
	return statusTarget{coreURL: coreURL, token: token, envToken: true}, nil
}

